export const PLANTILLA = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Merlin · Panel de ventas, ahorro y predicción</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js\"></script>\n<style>\n:root{--noche:#120d26;--noche2:#1d1640;--oro:#e9c349;--oro2:#fbf3d5;--ink:#1a1733;--ink2:#4a4766;--mut:#7c7a96;--line:#ebe9f3;--soft:#f7f6fb;--bg:#f3f2f8;\n--ok:#0f9d6b;--okbg:#e7f7f0;--at:#d68a00;--atbg:#fff5e0;--ri:#d93f3f;--ribg:#fdecec;--ag:#3f51d9;--agbg:#eaedff}\n*{box-sizing:border-box}\nbody{font-variant-numeric:lining-nums;margin:0;font-family:Inter,-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:var(--ink);background:var(--bg);font-size:15px;line-height:1.5;-webkit-font-smoothing:antialiased}\n.salir{float:right}.salir button{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);color:#d8d4f0;border-radius:999px;padding:7px 14px;font:inherit;font-size:13px;cursor:pointer}.salir button:hover{background:rgba(255,255,255,.16)}\nheader{background:radial-gradient(1200px 300px at 85% -40%,#3a2a7a 0%,transparent 60%),var(--noche);color:#fff;padding:26px 40px 0}\n.top{display:flex;align-items:center;gap:22px;flex-wrap:wrap}\n.top img{height:54px}\n.top .t h1{font-family:'Playfair Display',Georgia,serif;font-size:28px;margin:0;font-weight:700;letter-spacing:.2px}\n.top .t p{margin:2px 0 0;color:#bdb8dc;font-size:13.5px}\nnav{display:flex;gap:2px;flex-wrap:wrap;margin-top:22px}\nnav button{background:none;border:0;color:#bdb8dc;padding:13px 18px;font:inherit;font-size:14.5px;font-weight:600;cursor:pointer;border-bottom:3px solid transparent;border-radius:10px 10px 0 0}\nnav button:hover{color:#fff;background:rgba(255,255,255,.05)}\nnav button.on{color:#fff;border-bottom-color:var(--oro);background:rgba(255,255,255,.07)}\nmain{max-width:1380px;margin:0 auto;padding:30px 32px 80px}\n.sec{display:none}.sec.on{display:block;animation:ap .25s ease}\n@keyframes ap{from{opacity:0;transform:translateY(4px)}to{opacity:1}}\n.card{background:#fff;border-radius:20px;padding:26px 28px;margin-bottom:22px;box-shadow:0 1px 2px rgba(20,16,50,.04),0 6px 24px rgba(20,16,50,.05)}\nh2{font-family:'Playfair Display',Georgia,serif;font-size:24px;margin:0 0 6px;font-weight:700}\nh3{font-size:16.5px;margin:0 0 6px;font-weight:700}\n.lead{color:var(--ink2);font-size:15.5px;margin:0 0 20px;max-width:900px}\n.sub{color:var(--mut);font-size:13.5px;margin:0 0 16px}\n.hero{display:grid;grid-template-columns:1.3fr 1fr 1fr 1fr;gap:16px;margin-bottom:22px}\n@media(max-width:1100px){.hero{grid-template-columns:1fr 1fr}}\n.big{background:#fff;border-radius:20px;padding:22px 24px;box-shadow:0 1px 2px rgba(20,16,50,.04),0 6px 24px rgba(20,16,50,.05)}\n.big.dark{background:linear-gradient(135deg,var(--noche) 0%,#2b2160 100%);color:#fff}\n.big .v{font-size:36px;font-weight:800;letter-spacing:-1px;line-height:1.1}\n.big.dark .v{color:var(--oro)}\n.big .l{font-size:14px;font-weight:600;margin-top:6px}\n.big .s{font-size:13px;color:var(--mut);margin-top:4px}.big.dark .s{color:#c9c4ea}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:22px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}\n@media(max-width:1000px){.grid2,.grid3{grid-template-columns:1fr}}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth{text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.4px;color:var(--mut);padding:10px;border-bottom:1px solid var(--line);white-space:nowrap;font-weight:600}\ntd{padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top}td.n,th.n{text-align:right;white-space:nowrap}\ntbody tr:hover td{background:#fbfaff}\n.chip{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:4px 12px;font-size:12.5px;font-weight:700;letter-spacing:.2px;white-space:nowrap}\n.chip::before{content:'';width:8px;height:8px;border-radius:50%;background:currentColor}\n.c-ok{background:var(--okbg);color:var(--ok)}.c-at{background:var(--atbg);color:var(--at)}.c-ri{background:var(--ribg);color:var(--ri)}.c-ag{background:var(--agbg);color:var(--ag)}.c-gr{background:var(--soft);color:var(--mut)}\n.ok{color:var(--ok);font-weight:700}.at{color:var(--at);font-weight:700}.ri{color:var(--ri);font-weight:700}\n.ev{background:#fff;border-radius:20px;padding:24px 26px;margin-bottom:20px;box-shadow:0 1px 2px rgba(20,16,50,.04),0 6px 24px rgba(20,16,50,.05);border-left:6px solid var(--line)}\n.ev.e-ok{border-left-color:var(--ok)}.ev.e-at{border-left-color:var(--at)}.ev.e-ri{border-left-color:var(--ri)}.ev.e-ag{border-left-color:var(--ag)}\n.ev .hd{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;flex-wrap:wrap}\n.ev .hd h3{font-size:20px;margin:0}.ev .meta{color:var(--mut);font-size:13.5px}\n.veredicto{font-size:17px;font-weight:600;margin:14px 0 4px;line-height:1.45}\n.razon{color:var(--ink2);font-size:14.5px;margin:0}\n.track{position:relative;height:16px;background:var(--soft);border-radius:99px;margin:20px 0 8px}\n.track .vend{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:linear-gradient(90deg,#5b47d6,#8b7bf0)}\n.track .rng{position:absolute;top:0;bottom:0;border-radius:99px;background:repeating-linear-gradient(45deg,#d9d3fb,#d9d3fb 5px,#ece9fe 5px,#ece9fe 10px)}\n.track .cap{position:absolute;top:-6px;bottom:-6px;width:3px;background:var(--oro);border-radius:2px}\n.leyenda{display:flex;gap:18px;flex-wrap:wrap;font-size:12.5px;color:var(--mut)}\n.leyenda i{display:inline-block;width:12px;height:12px;border-radius:3px;margin-right:6px;vertical-align:-2px}\n.nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:16px}\n@media(max-width:900px){.nums{grid-template-columns:repeat(2,1fr)}}\n.nums div{background:var(--soft);border-radius:14px;padding:12px 14px}.nums .v{font-size:20px;font-weight:800}.nums .l{font-size:12.5px;color:var(--mut);line-height:1.35}\n.hacer{margin-top:16px;padding:14px 16px;border-radius:14px;background:var(--oro2);font-size:14.5px}\n.hacer b{display:block;font-size:12px;text-transform:uppercase;letter-spacing:.6px;color:#8a6a00;margin-bottom:4px}\n.ah{border:1px solid var(--line);border-radius:16px;padding:18px 20px;margin-bottom:14px}\n.ah .r{display:flex;justify-content:space-between;gap:14px;align-items:baseline;flex-wrap:wrap}\n.ah .monto{font-size:22px;font-weight:800;color:var(--ok)}\n.acc{display:grid;grid-template-columns:auto 1fr auto;gap:10px 14px;align-items:start;padding:12px 0;border-top:1px dashed var(--line);font-size:14px}\n.acc:first-of-type{border-top:0}\n.acc .q{font-weight:700;color:var(--ok);white-space:nowrap}.acc .q.re{color:var(--ag)}\n.acc .x{color:var(--mut);font-size:13px}\n.pal{border-radius:16px;padding:18px 20px;background:var(--soft)}\n.pal .n{font-size:11.5px;font-weight:800;color:#8a6a00;text-transform:uppercase;letter-spacing:.6px}\n.pal h4{margin:6px 0 6px;font-size:16px}.pal p{margin:0;font-size:14px;color:var(--ink2)}.pal .a{margin-top:10px;font-size:14px;font-weight:600}\nselect{font:inherit;font-size:14.5px;padding:10px 14px;border:1px solid var(--line);border-radius:12px;background:#fff;min-width:320px}\n.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:18px}\n.ch{position:relative;height:330px}.ch.s{height:250px}.ch.l{height:400px}\n.ads{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}\n.ad{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#fff;font-size:13px}.ad img{width:100%;height:160px;object-fit:cover;background:var(--soft);display:block}\n.ad .c{padding:12px 14px}.ad .c b{display:block;font-size:13.5px;margin-bottom:4px}.ad .c p{margin:6px 0 0;color:var(--mut);font-size:12.5px;max-height:54px;overflow:hidden}\n.note{font-size:13.5px;color:var(--ink2);line-height:1.6}\n.pill{display:inline-block;background:var(--soft);border-radius:999px;padding:3px 11px;font-size:12.5px;margin:2px;color:var(--ink2)}\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:22px}\n.kpi{background:#fff;border-radius:18px;padding:18px 20px;box-shadow:0 1px 2px rgba(20,16,50,.04),0 6px 24px rgba(20,16,50,.05)}\n.kpi .v{font-size:26px;font-weight:800;letter-spacing:-.5px}.kpi .l{font-size:13.5px;font-weight:600;margin-top:2px}.kpi .s{font-size:12.5px;color:var(--mut);margin-top:3px}\n.prec{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.prec div{background:var(--soft);border-radius:14px;padding:14px;text-align:center}.prec .v{font-size:24px;font-weight:800}.prec .l{font-size:12.5px;color:var(--mut)}\n.cap{display:flex;align-items:baseline;gap:14px;margin:44px 0 16px}.cap:first-child{margin-top:4px}\n.cap .num{font-family:'Playfair Display',Georgia,serif;font-size:18px;color:#b08a00;font-weight:700}\n.cap h2{font-size:30px;margin:0;line-height:1.15}.cap p{margin:4px 0 0;color:var(--ink2);font-size:15px}\n.titular,.cap h2,.cap .num,h2{font-variant-numeric:lining-nums}.titular{font-family:'Playfair Display',Georgia,serif;font-size:34px;line-height:1.2;font-weight:700;margin:0 0 8px;max-width:1050px}\n.titular em{font-style:normal;color:#5b47d6}\n.dec{display:grid;grid-template-columns:44px 1fr auto;gap:14px;align-items:center;padding:16px 4px;border-top:1px solid var(--line);cursor:pointer}\n.dec:hover{background:#fbfaff}.dec .i{width:36px;height:36px;border-radius:50%;background:var(--noche);color:var(--oro);display:grid;place-items:center;font-weight:800}\n.dec b{font-size:15.5px}.dec .x{color:var(--mut);font-size:13.5px}.dec .m{font-weight:800;font-size:18px;color:var(--ok);white-space:nowrap}\n.mini{display:grid;grid-template-columns:2.2fr 1fr 1.6fr 2fr;gap:14px;align-items:center;padding:14px 6px;border-top:1px solid var(--line);cursor:pointer;font-size:14px}\n.mini:hover{background:#fbfaff}.mini .bar{height:10px;background:var(--soft);border-radius:99px;position:relative;overflow:hidden}.mini .bar i{position:absolute;left:0;top:0;bottom:0;background:#8b7bf0;border-radius:99px}.mini .bar u{position:absolute;top:0;bottom:0;background:#d9d3fb}\n.aprend{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}@media(max-width:1000px){.aprend{grid-template-columns:1fr}}\n.aprend div{background:linear-gradient(135deg,#1d1640,#2b2160);color:#fff;border-radius:18px;padding:20px 22px;cursor:pointer}.aprend .k{color:var(--oro);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.6px}.aprend h4{font-family:'Playfair Display',Georgia,serif;font-size:21px;margin:8px 0 6px;line-height:1.25}.aprend p{margin:0;color:#c9c4ea;font-size:13.5px}\n.campas{margin-top:16px;border:1px solid var(--line);border-radius:14px;padding:6px 16px}.campas .acc{padding:10px 0}\n.fbtn{border:1px solid var(--line);background:#fff;border-radius:999px;padding:8px 16px;font:inherit;font-size:14px;font-weight:600;color:var(--ink2);cursor:pointer}.fbtn.on{background:var(--noche);color:#fff;border-color:var(--noche)}\n.ev-hd{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;flex-wrap:wrap}.ev-hd .monto{font-size:22px;font-weight:800;color:var(--ok)}\ndetails.qh{margin-top:14px;border-top:1px solid var(--line);padding-top:10px}details.qh summary{cursor:pointer;font-weight:700;color:#5b47d6;font-size:14.5px}\nfooter{color:var(--mut);font-size:12.5px;text-align:center;padding:20px}\n</style>\n</head>\n<body>\n<header>\n<form method=\"post\" action=\"/clientes/salir\" class=\"salir\"><input type=\"hidden\" name=\"area\" value=\"merlin\"><button>Cerrar sesión</button></form>\n<div class=\"top\"><img src=\"/reportes/logos/merlin.png?v=2\" alt=\"Merlin Comunicaciones\" onerror=\"this.style.display='none'\"><div class=\"t\"><h1>Panel de ventas, ahorro y predicción</h1><p>Ticketplus (venta real) + Meta Ads (inversión, públicos y creatividad) · actualizado al <span id=\"gen\"></span> · Muller y Pérez</p></div></div>\n<nav id=\"nav\"></nav>\n</header>\n<main>\n<section class=\"sec\" id=\"s-resumen\"></section>\n<section class=\"sec\" id=\"s-vigentes\"></section>\n<section class=\"sec\" id=\"s-ahorro\"></section>\n<section class=\"sec\" id=\"s-evento\"></section>\n<section class=\"sec\" id=\"s-carros\"></section>\n<section class=\"sec\" id=\"s-aprende\"></section>\n<section class=\"sec\" id=\"s-seg\"></section>\n<section class=\"sec\" id=\"s-crea\"></section>\n<section class=\"sec\" id=\"s-metodo\"></section>\n</main>\n<footer>Uso interno de Merlin Comunicaciones · preparado por Muller y Pérez</footer>\n<script>\nconst D=/*DATA*/;\nlet USD=D.usd;\nconst $=s=>document.querySelector(s);\nconst fmt=(n,d=0)=>n==null||isNaN(n)?'—':Number(n).toLocaleString('es-CL',{minimumFractionDigits:d,maximumFractionDigits:d});\nconst clp=n=>'$'+fmt(n);const mm=n=>'$'+fmt(n/1e6,0)+' MM';const usd=n=>'US$'+fmt(n);const pct=(n,d=0)=>fmt(n,d)+'%';\nconst MES=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];\nconst fecha=s=>{if(!s)return'—';const [y,m,d]=s.split('-');return `${+d} ${MES[m-1]} ${y}`};\nconst E=D.eventos.slice().sort((a,b)=>b.fecha.localeCompare(a.fecha));\nconst REAL=E.filter(e=>e.estado==='Realizado');const VIG=E.filter(e=>e.estado==='En venta').sort((a,b)=>a.fecha.localeCompare(b.fecha));\nconst COL=['#5b47d6','#0ea5e9','#e9a400','#10b981','#ef4444','#a855f7','#ec4899','#14b8a6'];\nconst TIPOS=[...new Set(E.map(e=>e.tipo))];const tcol=t=>COL[TIPOS.indexOf(t)%COL.length];\nconst charts={};function chart(id,cfg){if(charts[id])charts[id].destroy();const el=document.getElementById(id);if(!el)return;charts[id]=new Chart(el,cfg);return charts[id]}\nChart.defaults.font.family='Inter,-apple-system,Segoe UI,Roboto,Arial';Chart.defaults.font.size=12.5;Chart.defaults.color='#4a4766';Chart.defaults.plugins.legend.labels.usePointStyle=true;\nconst roas=e=>e.gasto?e.ingresos/(e.gasto*USD):null;\nconst S={resumen:'Resumen',vigentes:'Eventos en venta',ahorro:'Oportunidades',carros:'Carros abandonados',aprende:'Lo que enseña la historia',seg:'Públicos y ubicaciones',crea:'Creatividad',evento:'Archivo por evento',metodo:'Cómo se calcula'};\n$('#nav').innerHTML=Object.entries(S).map(([k,v],i)=>`<button data-s=\"${k}\" class=\"${i?'':'on'}\">${v}</button>`).join('');\n$('#nav').onclick=ev=>{const b=ev.target.closest('button');if(!b)return;ir(b.dataset.s)};\nfunction ir(s){document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('on',x.dataset.s===s));document.querySelectorAll('.sec').forEach(x=>x.classList.toggle('on',x.id==='s-'+s));render[s]();window.scrollTo({top:0})}\n$('#gen').textContent=fecha(D.generado);\nconst render={};\n\n/* ======== ESTADO DE UN EVENTO VIGENTE ======== */\nfunction estado(e){const p=e.proy;if(!p)return{c:'gr',t:'Sin datos',v:'',r:'',h:''};\n  const d=e.dias_al_evento,oc=p.ocup50,dem=p.dem_ocup;\n  if(dem>=103)return{c:'ag',t:'Se agota',v:`Va a vender todas las entradas: la demanda proyectada es ${pct(dem)} de la capacidad.`,r:`Lleva ${fmt(e.tickets_tp)} de ${fmt(e.cap_total)} (${pct(e.ocupacion)}) y vende ${fmt(p.ritmo_actual,0)} por día; para llenar le bastan ${fmt(p.ritmo_lleno,0)} por día.`,h:'Bajar la inversión diaria (queda dinero sobre la mesa en pauta), pasar a mensaje de «últimas entradas» y evaluar una función extra o subir el precio del tramo medio.'};\n  if(oc>=85)return{c:'ok',t:'Va bien',v:`Va bien: terminaría cerca de ${fmt(p.p50)} entradas (${pct(oc)} de la sala).`,r:`Lleva ${fmt(e.tickets_tp)} (${pct(e.ocupacion)}) y vende ${fmt(p.ritmo_actual,0)} por día. A ${d} días de la función, los eventos parecidos de Merlin tenían hecho el ${pct(p.frac)} de su venta.`,h:'Mantener la inversión, reforzar el fin de semana previo y no abrir campañas nuevas.'};\n  if(oc>=65)return{c:'at',t:'Atención',v:`Le falta: terminaría en ${fmt(p.p50)} entradas (${pct(oc)} de la sala).`,r:`Vende ${fmt(p.ritmo_actual,0)} por día y para llenar necesita ${fmt(p.ritmo_lleno,0)}. Lleva ${pct(e.ocupacion)} vendido.`,h:'Cambiar creatividad, concentrar en público 45–64 y feed de Instagram; revisar la sección Ahorro para mover presupuesto desde lo que no rinde.'};\n  return{c:'ri',t:'En riesgo',v:`En riesgo: terminaría en ${fmt(p.p50)} entradas (${pct(oc)} de la sala).`,r:`Vende ${fmt(p.ritmo_actual,0)} por día y para llenar necesitaría ${fmt(p.ritmo_lleno,0)}. Lleva ${pct(e.ocupacion)} vendido a ${d} días.`,h:'No subir pauta a ciegas: revisar precio, creatividad y público; si el costo por entrada sigue sobre lo histórico, recortar y aceptar menor ocupación.'};\n}\nconst chipE=e=>{const s=estado(e);return `<span class=\"chip c-${s.c}\">${s.t}</span>`};\n\n/* ======== AHORRO ======== */\nlet AFIL='';\nrender.ahorro=()=>{\n  const A=D.ahorro;if(!A){$('#s-ahorro').innerHTML='<div class=\"card\"><h2>Oportunidades</h2><p>Sin datos de campañas activas.</p></div>';return}\n  const evs=A.eventos.filter(x=>x.slug),sel=AFIL?evs.filter(x=>x.slug===AFIL):evs;\n  const est={bien:['c-ok','Bien'],'atención':['c-at','Atención'],mal:['c-ri','Bajo lo histórico'],'poco gasto':['c-gr','Poco gasto']};\n  const nb=evs.reduce((a,x)=>{x.items.forEach(i=>a[i[7]]=(a[i[7]]||0)+1);return a},{});\n  $('#s-ahorro').innerHTML=`<div class=\"cap\"><span class=\"num\">01</span><div><h2>Oportunidades en la pauta actual</h2><p>Estimación prudente para las <b>próximas 2 semanas</b>; se recalcula cada semana con la venta real.</p></div></div>\n  <div class=\"hero\">\n   <div class=\"big dark\"><div class=\"v\">${usd(A.total)}</div><div class=\"l\">ahorro posible en 2 semanas</div><div class=\"s\">${pct(100*A.total/Math.max(1,A.gasto_restante))} de la pauta de esas 2 semanas · recortes de máximo 40%</div></div>\n   <div class=\"big\"><div class=\"v\">${usd(A.reasignable)}</div><div class=\"l\">a mover a lo que sí vende</div><div class=\"s\">misma campaña, no es ahorro</div></div>\n   <div class=\"big\"><div class=\"v\">${nb.bien||0} <span style=\"font-size:20px;color:var(--mut)\">de ${Object.values(nb).reduce((a,b)=>a+b,0)}</span></div><div class=\"l\">piezas activas rinden bien</div><div class=\"s\">campañas, conjuntos y anuncios</div></div>\n   <div class=\"big\"><div class=\"v\" style=\"color:var(--ri)\">${(nb.mal||0)}</div><div class=\"l\">rinden bajo lo histórico</div><div class=\"s\">${nb['atención']||0} más en atención</div></div>\n  </div>\n  <div class=\"row\"><button class=\"fbtn ${AFIL?'':'on'}\" data-f=\"\">Todos</button>${evs.map(x=>`<button class=\"fbtn ${AFIL===x.slug?'on':''}\" data-f=\"${x.slug}\">${x.nombre.replace(/ - .*/,'').toLowerCase().replace(/(^|\\s)\\S/g,c=>c.toUpperCase())}${/Valpara/.test(x.nombre)?' · Valpo':''}</button>`).join('')}</div>\n  ${sel.map(ev=>{const e=E.find(x=>x.slug===ev.slug);return `<div class=\"card\"><div class=\"ev-hd\"><div><h3 style=\"font-size:19px;margin:0\">${ev.nombre}</h3><div class=\"sub\" style=\"margin:2px 0 0\">${e?fecha(e.fecha)+' · faltan '+e.dias_al_evento+' días · ':''}US$${fmt(ev.diario)} al día en Meta · referencia histórica US$${fmt(ev.ref_cpa)} por compra</div></div><div style=\"text-align:right\">${e?chipE(e):''}<div class=\"monto\">${ev.ahorro?usd(ev.ahorro):'—'}</div><div class=\"sub\" style=\"margin:0\">ahorro 2 semanas${ev.mover?` · mover ${usd(ev.mover)}`:''}</div></div></div>\n   <table style=\"margin-top:12px\"><thead><tr><th>Nivel</th><th>Pieza activa</th><th class=\"n\">Gasto 14 días</th><th class=\"n\">Compras</th><th class=\"n\">US$ por compra</th><th class=\"n\">Retorno</th><th>Estado</th></tr></thead><tbody>${ev.items.map(i=>`<tr><td class=\"x\" style=\"color:var(--mut)\">${i[0]}</td><td>${i[1]}</td><td class=\"n\">${usd(i[2])}</td><td class=\"n\">${fmt(i[3])}</td><td class=\"n\"><b>${fmt(i[4],0)}</b></td><td class=\"n\">${fmt(i[5],1)}x</td><td><span class=\"chip ${est[i[7]][0]}\">${est[i[7]][1]}</span></td></tr>`).join('')}</tbody></table>\n   ${ev.acciones.length?`<details class=\"qh\"><summary>Qué hacer (${ev.acciones.length})</summary>${ev.acciones.map(a=>`<div class=\"acc\"><span class=\"chip ${a.reasignar?'c-ag':'c-ok'}\">${a.tipo}</span><div><b>${a.que}</b><div class=\"x\">${a.porque}</div></div><div class=\"q ${a.reasignar?'re':''}\">${a.monto?(a.reasignar?'mover ':'')+usd(a.monto):''}</div></div>`).join('')}</details>`:'<div class=\"hacer\" style=\"background:var(--okbg)\"><b style=\"color:var(--ok)\">Sin cambios</b>Todo rinde dentro de lo histórico.</div>'}</div>`}).join('')}\n  ${AFIL?'':`<div class=\"cap\"><span class=\"num\">03</span><div><h2>Oportunidades fuera de la pauta</h2><p>Lo que dice la historia de ventas y la base de compradores.</p></div></div>\n  <div class=\"grid3\">${palancas().filter(p=>/Precio|Calendario|Días/.test(p[0])).map(p=>`<div class=\"pal\"><div class=\"n\">${p[0]}</div><h4>${p[1]}</h4><p>${p[2]}</p><div class=\"a\">→ ${p[3]}</div></div>`).join('')}${D.recompra?`<div class=\"pal\"><div class=\"n\">Base propia</div><h4>Quien vuelve a comprar pesa ${pct(100*D.recompra.rep.ventas/D.recompra.ventas,0)} de la venta 2025</h4><p>Compra ${fmt(D.recompra.rep.tickets/D.recompra.rep.n,1)} entradas por persona. El % de público recurrente por evento se está recalculando con todos los eventos 2024–2026 de Ticketplus.</p><div class=\"a\">→ Público de compradores anteriores en Meta y correo a la base al abrir cada venta.</div></div>`:''}</div>\n  <div class=\"card\" style=\"margin-top:22px\"><h3>Con qué se compara (la historia de Merlin)</h3><p class=\"sub\">Costo por compra según Meta en eventos ya realizados, por tipo y por etapa de la venta.</p>\n  <table><thead><tr><th>Tipo de evento</th><th class=\"n\">Más de 30 días antes</th><th class=\"n\">Últimos 30 días</th><th class=\"n\">Eventos</th></tr></thead><tbody>${Object.entries(A.referencias).map(([t,r])=>`<tr><td>${t}</td><td class=\"n\">US$${fmt(r.temprano,1)}</td><td class=\"n\">US$${fmt(r.final,1)}</td><td class=\"n\">${r.n}</td></tr>`).join('')}</tbody></table></div>`}`;\n  document.querySelectorAll('.fbtn').forEach(b=>b.onclick=()=>{AFIL=b.dataset.f;render.ahorro()});\n};\n/* ======== CARROS ABANDONADOS ======== */\nrender.carros=()=>{\n  const A=D.abandono;if(!A){$('#s-carros').innerHTML='<div class=\"card\">Sin datos</div>';return}\n  const T=A.total,conv=100*T.conf/(T.conf+T.perd),porC=T.exp/T.conf;\n  const DIAS=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];\n  const dur=Object.fromEntries(A.duracion),dTot=A.duracion.reduce((a,x)=>a+x[1],0);\n  const tiempo=(dur['11–15 min']||0)+(dur['16–30 min']||0)+(dur['más de 30']||0),rapido=(dur['≤1 min']||0)+(dur['2–5 min']||0);\n  const nom=k=>(E.find(e=>e.slug===k||e.nombre===k)||{}).nombre||k;\n  const fila=(r,lbl)=>`<tr><td>${lbl||r[0]}</td><td class=\"n\">${fmt(r[1])}</td><td class=\"n\">${fmt(r[2])}</td><td class=\"n\"><b>${fmt(100-r[3],0)}%</b></td><td class=\"n\">${fmt(r[2]/Math.max(1,r[1]),1)}</td></tr>`;\n  const thead='<thead><tr><th></th><th class=\"n\">Compras</th><th class=\"n\">Carros sin compra</th><th class=\"n\">Conversión</th><th class=\"n\">Carros por compra</th></tr></thead>';\n  const B=A.base;\n  const PP=A.personas,PT=PP.total,pab=100*PT.abandono_confirmado/(PT.compradores+PT.abandono_confirmado),ratio=PT.compradores/PT.abandono_confirmado;\n  const filaP=(k,v)=>`<tr><td>${nom(k)}</td><td class=\"n\">${fmt(v.compradores)}</td><td class=\"n\"><b>${fmt(v.abandono_confirmado)}</b></td><td class=\"n\">${fmt(v.volvieron)}</td><td class=\"n\"><b>${pct(100*v.abandono_confirmado/Math.max(1,v.compradores+v.abandono_confirmado),0)}</b></td><td class=\"n\">${v.abandono_confirmado?fmt(v.compradores/v.abandono_confirmado,1):'—'}</td><td class=\"n\" style=\"color:var(--mut)\">${fmt(v.carros_sin_datos)}</td></tr>`;\n  $('#s-carros').innerHTML=`<div class=\"card\" style=\"padding:34px 36px\"><div class=\"sub\" style=\"text-transform:uppercase;letter-spacing:.8px;font-weight:700;margin-bottom:10px\">Carros abandonados · eventos en venta</div>\n   <p class=\"titular\">Por cada <em>${fmt(ratio,0)} compradores</em> hay 1 persona que abrió carro con sus datos y no compró.</p>\n   <p class=\"lead\" style=\"margin:0\">Solo se cuenta como abandono a quien dejó su correo y no compró ese evento después: <b>${fmt(PT.abandono_confirmado)} personas</b>, ${pct(pab,0)} de quienes llegaron al pago. Otras ${fmt(PT.volvieron)} abandonaron un carro pero volvieron y compraron. Los ${fmt(PT.carros_sin_datos)} carros sin datos (la persona no alcanzó a poner su correo) se muestran aparte: no se puede saber si después compraron.</p></div>\n  <div class=\"hero\">\n   <div class=\"big dark\"><div class=\"v\">${fmt(PT.abandono_confirmado)}</div><div class=\"l\">personas abandonaron y no compraron</div><div class=\"s\">con correo · listas para recuperar</div></div>\n   <div class=\"big\"><div class=\"v\">${pct(pab,0)}</div><div class=\"l\">abandono al llegar al pago</div><div class=\"s\">${fmt(PT.compradores)} compradores vs ${fmt(PT.abandono_confirmado)} que no compraron</div></div>\n   <div class=\"big\"><div class=\"v\">${fmt(PT.volvieron)}</div><div class=\"l\">abandonaron y volvieron a comprar</div><div class=\"s\">${pct(100*PT.volvieron/(PT.volvieron+PT.abandono_confirmado),0)} de quienes abandonan, vuelve solo</div></div>\n   <div class=\"big\"><div class=\"v\">${fmt(PT.carros_sin_datos)}</div><div class=\"l\">carros sin datos</div><div class=\"s\">elegían entradas y no dejaron correo; incluye reintentos y gente comparando</div></div>\n  </div>\n  <div class=\"cap\"><span class=\"num\">01</span><div><h2>Compra vs carro abandonado, por evento</h2><p>Personas distintas, mismo período (desde la primera orden vencida disponible de cada evento). Datos verificados: las compras calzan con Ticketplus.</p></div></div>\n  <div class=\"card\"><table><thead><tr><th>Evento</th><th class=\"n\">Compradores</th><th class=\"n\">Abandonaron sin volver</th><th class=\"n\">Abandonaron y volvieron</th><th class=\"n\">% abandono</th><th class=\"n\">Compradores por abandono</th><th class=\"n\">Carros sin datos</th></tr></thead><tbody>${Object.entries(PP.por_evento).sort((a,b)=>b[1].compradores-a[1].compradores).map(([k,v])=>filaP(k,v)).join('')}</tbody></table>\n  <div class=\"ch\" style=\"margin-top:18px\"><canvas id=\"c-cev\"></canvas></div></div>\n  <div class=\"cap\"><span class=\"num\">02</span><div><h2>Motivos</h2><p>Ticketplus no registra el motivo; se infiere de cuánto tiempo estuvo abierto el carro.</p></div></div>\n  <div class=\"grid2\"><div class=\"card\"><h3>Cuánto duró el carro antes de vencer</h3><div class=\"ch\"><canvas id=\"c-dur\"></canvas></div></div>\n  <div class=\"card\"><h3>Lectura</h3><div class=\"note\">\n   <p><b>${pct(100*tiempo/dTot,0)} vence por tiempo (10 minutos o más).</b> La persona eligió entradas y no terminó: lo más probable es que dudara con el precio o la ubicación, que se cayera el pago o que estuviera comparando funciones.</p>\n   <p><b>${pct(100*rapido/dTot,0)} se cierra en menos de 5 minutos.</b> Probable rechazo del pago o arrepentimiento inmediato.</p>\n   <p><b>${pct(100*PT.volvieron/(PT.volvieron+PT.abandono_confirmado),0)} de quienes abandonan con datos vuelve y compra</b> (${fmt(PT.volvieron)} personas): parte del abandono es fricción en el pago, no pérdida.</p>\n   <p><b>1 entrada abandona ${pct(A.cantidad.find(r=>r[0]==='1')?.[3]||0,0)}</b>, contra ${pct(A.cantidad.find(r=>r[0]==='2')?.[3]||0,0)} en 2 entradas: quien compra solo está explorando precios.</p>\n   <p><b>El Booster de Ticketplus convierte mejor</b> (${fmt(100-(A.canal.find(r=>r[0]==='google_ads_tp')?.[3]||0),0)}% de los carros terminan en compra) que el link directo (${fmt(100-(A.canal.find(r=>r[0]==='directo')?.[3]||0),0)}%): el tráfico de búsqueda llega más decidido que el de redes.</p></div></div></div>\n  <div class=\"cap\"><span class=\"num\">03</span><div><h2>Patrones y perfiles</h2><p>Sobre todos los intentos (con y sin datos): % de intentos que terminan en compra. Sirve para comparar, no como tasa exacta.</p></div></div>\n  <div class=\"grid2\"><div class=\"card\"><h3>Por hora del día</h3><div class=\"ch s\"><canvas id=\"c-hora\"></canvas></div></div>\n  <div class=\"card\"><h3>Por día de la semana</h3><div class=\"ch s\"><canvas id=\"c-dia\"></canvas></div></div></div>\n  <div class=\"grid3\"><div class=\"card\"><h3>Por cantidad de entradas</h3><table>${thead}<tbody>${A.cantidad.map(r=>fila(r,r[0]+(r[0]==='1'?' entrada':' entradas'))).join('')}</tbody></table></div>\n  <div class=\"card\"><h3>Por precio de la entrada</h3><table>${thead}<tbody>${A.precio.map(r=>fila(r)).join('')}</tbody></table></div>\n  <div class=\"card\"><h3>Por canal</h3><table>${thead}<tbody>${A.canal.map(r=>fila(r,r[0]==='directo'?'Link directo (Meta, orgánico)':r[0]==='google_ads_tp'?'Booster Ticketplus (Google)':r[0])).join('')}</tbody></table></div></div>\n  <div class=\"cap\"><span class=\"num\">04</span><div><h2>Qué hacer</h2><p>Ordenado por impacto esperado.</p></div></div>\n  <div class=\"grid3\">\n   <div class=\"pal\"><div class=\"n\">Recuperar</div><h4>Correo a las ${fmt(PT.abandono_confirmado)} personas que abandonaron</h4><p>Correo dentro de 1–2 horas: «tus entradas siguen disponibles», con link directo a la función que eligió. Lista lista en la carpeta privada de Merlin.</p></div>\n   <div class=\"pal\"><div class=\"n\">Capturar</div><h4>Pedir el correo antes de elegir butacas</h4><p>Hoy ${pct(100*PT.carros_sin_datos/(PT.carros_sin_datos+PT.abandono_confirmado+PT.volvieron),0)} de los carros vence sin correo y no se puede recuperar. Pedirlo a Ticketplus en el primer paso.</p></div>\n   <div class=\"pal\"><div class=\"n\">Remarketing</div><h4>Público en Meta de quien abrió carro y no compró</h4><p>Con el píxel de Ticketplus (evento InitiateCheckout sin Purchase), últimos 7 días, mensaje de «últimas entradas» por función.</p></div>\n   <div class=\"pal\"><div class=\"n\">Fricción</div><h4>Revisar el paso de pago</h4><p>${pct(100*PT.volvieron/(PT.volvieron+PT.abandono_confirmado),0)} de quienes abandonan vuelve a comprar después: el pago o la elección de butacas genera fricción. Revisar con Ticketplus medios de pago y tiempos.</p></div>\n   <div class=\"pal\"><div class=\"n\">Base propia</div><h4>${B?fmt(B.total):'—'} contactos para acciones de correo</h4><p>${B?Object.entries(B.segmentos).map(([k,v])=>k+' '+fmt(v)).join(' · '):''}. Excluye a quienes se desuscribieron en Ticketplus.</p></div>\n   <div class=\"pal\"><div class=\"n\">1 entrada</div><h4>Ofrecer el «+1»</h4><p>Quien abre carro con 1 entrada abandona mucho más: probar mensaje de dos entradas o precio pareja en Meta.</p></div>\n  </div>`;\n  const ev=Object.entries(PP.por_evento).sort((a,b)=>b[1].compradores-a[1].compradores);\n  chart('c-cev',{type:'bar',data:{labels:ev.map(r=>nom(r[0]).replace(/ - .*/,'')+(/valpara/i.test(r[0])?' Valpo':'')),datasets:[{label:'Compradores',data:ev.map(r=>r[1].compradores),backgroundColor:'#5b47d6',borderRadius:6},{label:'Abandonaron sin volver',data:ev.map(r=>r[1].abandono_confirmado),backgroundColor:'#ef8a8a',borderRadius:6},{label:'Abandonaron y volvieron',data:ev.map(r=>r[1].volvieron),backgroundColor:'#c9c1f7',borderRadius:6}]},options:{maintainAspectRatio:false,scales:{x:{grid:{display:false}},y:{grid:{color:'#f0eef7'}}}}});\n  chart('c-dur',{type:'bar',data:{labels:['≤1 min','2–5 min','6–10 min','11–15 min','16–30 min','más de 30'],datasets:[{data:['≤1 min','2–5 min','6–10 min','11–15 min','16–30 min','más de 30'].map(k=>dur[k]||0),backgroundColor:'#8b7bf0',borderRadius:6}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{grid:{color:'#f0eef7'}}}}});\n  const conv_=r=>+(100-r[3]).toFixed(1);\n  chart('c-hora',{type:'line',data:{labels:A.hora.map(r=>r[0]+'h'),datasets:[{data:A.hora.map(conv_),borderColor:'#5b47d6',tension:.3,pointRadius:2}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{grid:{color:'#f0eef7'},ticks:{callback:v=>v+'%'}},x:{grid:{display:false}}}}});\n  chart('c-dia',{type:'bar',data:{labels:A.dia.map(r=>DIAS[r[0]]),datasets:[{data:A.dia.map(conv_),backgroundColor:'#c9c1f7',borderRadius:6}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{grid:{color:'#f0eef7'},ticks:{callback:v=>v+'%'}},x:{grid:{display:false}}}}});\n};\n\n/* ======== RESUMEN ======== */\nrender.resumen=()=>{\n  const A=D.ahorro||{eventos:[],total:0,reasignable:0},cnt=c=>VIG.filter(e=>estado(e).c===c).length;\n  const ingHoy=VIG.reduce((a,e)=>a+e.ingresos,0),ingP=VIG.reduce((a,e)=>a+(e.proy?.ing50||0),0);\n  const malos=VIG.filter(e=>['ri','at'].includes(estado(e).c));\n  const tit=`${VIG.length} eventos en venta: <em>${cnt('ag')} se van a agotar</em>${cnt('ok')?`, ${cnt('ok')} va${cnt('ok')>1?'n':''} bien`:''}${malos.length?` y ${malos.length} necesita${malos.length>1?'n':''} ayuda (${malos.map(e=>e.nombre.replace(/ - .*/,'').toLowerCase().replace(/(^|\\s)\\S/g,x=>x.toUpperCase())+' '+e.ciudad).join(', ')})`:''}.`;\n  const acc=[];for(const ev of A.eventos)for(const a of ev.acciones)if(a.monto>0)acc.push({...a,ev:ev.nombre,slug:ev.slug});\n  acc.sort((a,b)=>b.monto-a.monto);\n  const dec=[...malos.map(e=>({tipo:'Revisar',que:`${e.nombre}: ${estado(e).v}`,porque:estado(e).h,monto:0,slug:e.slug,ir:'vigentes'})),...acc.slice(0,5).map(a=>({...a,ir:'vigentes'}))];\n  const pal=palancas();const R=D.recompra;\n  $('#s-resumen').innerHTML=`<div class=\"card\" style=\"padding:34px 36px\"><div class=\"sub\" style=\"text-transform:uppercase;letter-spacing:.8px;font-weight:700;margin-bottom:10px\">Hoy, ${fecha(D.generado)}</div>\n   <p class=\"titular\">${tit}</p>\n   <p class=\"lead\" style=\"margin:0\">Se pueden ahorrar <b>${usd(A.total)}</b> en Meta en las próximas 2 semanas y mover otros <b>${usd(A.reasignable)}</b> a lo que sí vende. Los eventos en venta llevan ${mm(ingHoy)} y terminarían cerca de <b>${mm(ingP)}</b>.</p></div>\n  <div class=\"hero\">\n   <div class=\"big dark\" style=\"cursor:pointer\" onclick=\"ir('ahorro')\"><div class=\"v\">${usd(A.total)}</div><div class=\"l\">ahorro posible en 2 semanas</div><div class=\"s\">${pct(100*A.total/Math.max(1,A.gasto_restante))} de la pauta de esas 2 semanas · ver oportunidades →</div></div>\n   <div class=\"big\" style=\"cursor:pointer\" onclick=\"ir('vigentes')\"><div class=\"v\">${mm(ingP)}</div><div class=\"l\">venta proyectada de los eventos en venta</div><div class=\"s\">hoy van ${mm(ingHoy)} · rango según historia</div></div>\n   <div class=\"big\" style=\"cursor:pointer\" onclick=\"ir('vigentes')\"><div class=\"v\">${cnt('ag')} de ${VIG.length}</div><div class=\"l\">eventos que se van a agotar</div><div class=\"s\">ahí sobra pauta</div></div>\n   <div class=\"big\" style=\"cursor:pointer\" onclick=\"ir('aprende')\"><div class=\"v\">${R?pct(100*R.rep.ventas/R.ventas,0):'—'}</div><div class=\"l\">de la venta 2025 la hizo quien compró 2 o más eventos</div><div class=\"s\">% de público recurrente por evento: en revisión</div></div>\n  </div>\n  <div class=\"cap\"><span class=\"num\">01</span><div><h2>Qué hacer esta semana</h2><p>Ordenado por impacto. Click para ver el detalle.</p></div></div>\n  <div class=\"card\" style=\"padding:10px 24px\">${dec.map((d,i)=>`<div class=\"dec\" data-s=\"${d.slug||''}\"><div class=\"i\">${i+1}</div><div><b>${d.que}</b><div class=\"x\">${d.ev?d.ev+' · ':''}${d.porque}</div></div><div class=\"m\" style=\"${d.reasignar?'color:var(--ag)':''}\">${d.monto?(d.reasignar?'mover ':'')+usd(d.monto):''}</div></div>`).join('')}</div>\n  <div class=\"cap\"><span class=\"num\">02</span><div><h2>Cómo van los eventos en venta</h2><p>Barra: vendido hoy (morado) y proyección al cierre (lila) sobre la capacidad.</p></div></div>\n  <div class=\"card\" style=\"padding:10px 24px\"><div class=\"mini\" style=\"cursor:default;font-size:12px;color:var(--mut);text-transform:uppercase;letter-spacing:.4px\"><div>Evento</div><div>Estado</div><div>Vendido → proyección</div><div></div></div>${VIG.map(e=>{const s=estado(e),p=e.proy;return `<div class=\"mini\" data-s=\"${e.slug}\"><div><b>${e.nombre}</b><div class=\"x\" style=\"color:var(--mut);font-size:13px\">${e.ciudad} · ${fecha(e.fecha)} · faltan ${e.dias_al_evento} días</div></div><div><span class=\"chip c-${s.c}\">${s.t}</span></div><div>${pct(e.ocupacion)} → <b>${pct(p.ocup50)}</b>${p.dem_ocup>103?` <span class=\"x\" style=\"color:var(--mut)\">(demanda ${pct(p.dem_ocup)})</span>`:''}</div><div class=\"bar\"><u style=\"width:${Math.min(100,p.ocup50)}%\"></u><i style=\"width:${Math.min(100,e.ocupacion)}%\"></i></div></div>`}).join('')}</div>\n  <div class=\"cap\"><span class=\"num\">03</span><div><h2>Tres aprendizajes que mueven la aguja</h2><p>De ${REAL.length} eventos realizados. Click para ver la historia completa.</p></div></div>\n  <div class=\"aprend\">${[pal[1],pal[2],R?['Base propia',`Quien repite compra ${fmt(R.rep.tickets/R.rep.n,1)} entradas; quien no, ${fmt((R.tickets-R.rep.tickets)/(R.compradores-R.rep.n),1)}`,`Dentro de 2025, quienes compraron 2 o más eventos generaron ${pct(100*R.rep.ventas/R.ventas,0)} de la venta. El % de público recurrente por evento está en revisión.`]:pal[0]].map(p=>`<div onclick=\"ir('aprende')\"><div class=\"k\">${p[0]}</div><h4>${p[1]}</h4><p>${p[2]}</p></div>`).join('')}</div>`;\n  document.querySelectorAll('#s-resumen [data-s]').forEach(el=>el.onclick=()=>{const s=el.dataset.s;ir('vigentes');if(s){const t=document.getElementById('ev-'+s);if(t)setTimeout(()=>t.scrollIntoView({behavior:'smooth'}),60)}});\n};\n\n/* ======== VIGENTES ======== */\nrender.vigentes=()=>{\n  const cnt=c=>VIG.filter(e=>estado(e).c===c).length;\n  $('#s-vigentes').innerHTML=`<div class=\"cap\"><span class=\"num\">01</span><div><h2>Eventos en venta: ¿cómo van?</h2><p>Semáforo, proyección al cierre y qué hacer con la pauta de cada uno.</p></div></div><div class=\"card\"><p class=\"lead\" style=\"margin-top:0\">Cada evento se compara con lo que vendían los eventos anteriores de Merlin a la misma distancia de la función. El color dice si va bien; abajo, qué hacer.</p>\n  <div class=\"row\"><span class=\"chip c-ag\">Se agota · ${cnt('ag')}</span><span class=\"chip c-ok\">Va bien · ${cnt('ok')}</span><span class=\"chip c-at\">Atención · ${cnt('at')}</span><span class=\"chip c-ri\">En riesgo · ${cnt('ri')}</span></div>\n  <div class=\"leyenda\"><span><i style=\"background:#6a57e0\"></i>vendido hoy</span><span><i style=\"background:#ddd7fc\"></i>rango proyectado al cierre</span><span><i style=\"background:var(--oro)\"></i>capacidad</span></div></div>\n  ${VIG.map(e=>{const p=e.proy,s=estado(e),mx=Math.max(e.cap_total,p.alto,p.demanda||0)*1.04;\n   return `<div class=\"ev e-${s.c}\" id=\"ev-${e.slug}\"><div class=\"hd\"><div><h3>${e.nombre}</h3><div class=\"meta\">${e.tipo} · ${e.ciudad} · ${fecha(e.fecha)} · ${e.funciones} ${e.funciones>1?'funciones':'función'} · faltan ${e.dias_al_evento} días</div></div><span class=\"chip c-${s.c}\" style=\"font-size:14px;padding:7px 16px\">${s.t}</span></div>\n   <p class=\"veredicto\">${s.v}</p><p class=\"razon\">${s.r}</p>\n   <div class=\"track\"><div class=\"rng\" style=\"left:${100*p.bajo/mx}%;width:${Math.max(.8,100*(p.alto-p.bajo)/mx)}%\"></div><div class=\"vend\" style=\"width:${100*e.tickets_tp/mx}%\"></div><div class=\"cap\" style=\"left:${100*e.cap_total/mx}%\"></div></div>\n   <div class=\"nums\"><div><div class=\"v\">${fmt(e.tickets_tp)}</div><div class=\"l\">entradas vendidas (${pct(e.ocupacion)})</div></div><div><div class=\"v\">${fmt(p.p50)}</div><div class=\"l\">proyección al cierre (${fmt(p.bajo)}–${fmt(p.alto)})</div></div><div><div class=\"v\">${mm(p.ing50)}</div><div class=\"l\">venta proyectada</div></div><div><div class=\"v\">${fmt(roas(e),1)}x</div><div class=\"l\">retorno a la fecha · ${usd(e.gasto)} en Meta</div></div></div>\n   <div class=\"hacer\"><b>Qué hacer</b>${s.h}</div>\n   ${campasHTML(e)}\n   <div class=\"ch s\" style=\"margin-top:18px\"><canvas id=\"vc-${e.slug}\"></canvas></div><div class=\"sub\" style=\"margin-top:6px\">Morado: este evento (en % de su proyección). Gris: eventos anteriores del mismo tipo. Eje: días antes de la función.</div></div>`}).join('')}`;\n  for(const e of VIG)curvaChart('vc-'+e.slug,e,true);\n};\nfunction campasHTML(e){const a=(D.ahorro?.eventos||[]).find(x=>x.slug===e.slug);if(!a)return '<div class=\"campas\"><div class=\"acc\"><span class=\"chip c-gr\">Sin pauta activa</span><div>No hay campañas Meta activas para este evento.</div><div></div></div></div>';\n return `<div class=\"campas\"><div class=\"sub\" style=\"margin:10px 0 2px\"><b style=\"color:var(--ink)\">Pauta Meta:</b> ${a.campanas.join(' · ')} · US$${fmt(a.diario)} al día${a.ahorro?` · <b class=\"ok\">ahorro posible ${usd(a.ahorro)}</b>`:''}${a.mover?` · <b style=\"color:var(--ag)\">mover ${usd(a.mover)}</b>`:''}</div>${a.acciones.map(x=>`<div class=\"acc\"><span class=\"chip ${x.reasignar?'c-ag':'c-ok'}\">${x.tipo}</span><div><b>${x.que}</b><div class=\"x\">${x.porque}</div></div><div class=\"q ${x.reasignar?'re':''}\">${x.monto?(x.reasignar?'mover ':'ahorro ')+usd(x.monto):''}</div></div>`).join('')||'<div class=\"acc\"><span class=\"chip c-ok\">Rinde bien</span><div>Todo dentro de lo histórico.</div><div></div></div>'}</div>`}\nfunction curvaChart(id,e,proy){\n  const ref=REAL.filter(r=>r.tipo===e.tipo);const pool=ref.length>=3?ref:REAL;\n  const maxd=Math.min(150,Math.max(...pool.map(r=>r.dias_venta),e.dias_venta||0));\n  const ds=pool.slice(0,14).map(r=>({label:r.nombre,data:r.curva.filter(c=>c[0]<=maxd).map(c=>({x:-c[0],y:100*c[1]})),borderColor:'rgba(140,136,170,.35)',borderWidth:1.2,pointRadius:0,stepped:true}));\n  const k=proy&&e.proy?e.tickets/(e.proy.p50*e.tickets/Math.max(1,e.tickets_tp)):1;\n  ds.push({label:e.nombre,data:e.curva.map(c=>({x:-c[0],y:100*c[1]*k})),borderColor:'#5b47d6',borderWidth:3.5,pointRadius:0,stepped:true});\n  chart(id,{type:'line',data:{datasets:ds},options:{maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${fmt(c.raw.y)}% a ${-c.raw.x} días`}}},scales:{x:{type:'linear',min:-maxd,max:3,grid:{color:'#f0eef7'},title:{display:true,text:'días antes de la función'},ticks:{callback:v=>-v}},y:{min:0,max:105,grid:{color:'#f0eef7'},ticks:{callback:v=>v+'%'}}}}});\n}\n\n/* ======== DETALLE POR EVENTO ======== */\nlet SEL=VIG[0]?.slug||E[0].slug;\nrender.evento=()=>{\n  const e=E.find(x=>x.slug===SEL);\n  const ads=D.creatividades.filter(c=>c.slug===e.slug&&c.gasto>5).map(c=>({...c,r:c.valor/c.gasto})).sort((a,b)=>b.compras-a.compras);\n  const zt=e.zonas.reduce((a,x)=>a+x[2],0),ct=e.canales.reduce((a,x)=>a+x[1],0);\n  $('#s-evento').innerHTML=`<div class=\"row\"><select id=\"evsel\">${['En venta','Realizado'].map(g=>`<optgroup label=\"${g==='En venta'?'Vigentes':'Realizados'}\">${E.filter(x=>x.estado===g).map(x=>`<option value=\"${x.slug}\" ${x.slug===SEL?'selected':''}>${fecha(x.fecha)} · ${x.nombre} · ${x.ciudad}</option>`).join('')}</optgroup>`).join('')}</select> ${e.estado==='En venta'?chipE(e):`<span class=\"chip c-gr\">${e.perfil}</span>`} <span class=\"pill\">${e.tipo}</span><span class=\"pill\">${e.ciudad}</span><span class=\"pill\">${e.funciones} ${e.funciones>1?'funciones':'función'}</span></div>\n  <div class=\"kpis\">\n   <div class=\"kpi\"><div class=\"v\">${mm(e.ingresos)}</div><div class=\"l\">venta Ticketplus</div><div class=\"s\">precio promedio ${clp(e.precio_prom)}</div></div>\n   <div class=\"kpi\"><div class=\"v\">${fmt(e.tickets_tp)}</div><div class=\"l\">entradas</div><div class=\"s\">${pct(e.ocupacion)} de ${fmt(e.cap_total)} butacas</div></div>\n   <div class=\"kpi\"><div class=\"v\">${usd(e.gasto)}</div><div class=\"l\">inversión Meta</div><div class=\"s\">US$${fmt(e.cpt,2)} por entrada</div></div>\n   <div class=\"kpi\"><div class=\"v\">${fmt(roas(e),1)}x</div><div class=\"l\">retorno</div><div class=\"s\">venta ÷ inversión</div></div>\n   <div class=\"kpi\"><div class=\"v\">${pct(e.antes30)}</div><div class=\"l\">vendido con +30 días</div><div class=\"s\">${pct(e.ult14)} en las 2 últimas semanas</div></div>\n  </div>\n  <div class=\"card\"><h3>Venta diaria e inversión diaria</h3><p class=\"sub\">Venta desde el ${fecha(e.inicio_venta)} · primera función ${fecha(e.fecha)} · día de más venta ${fecha(e.pico)}. Costo por entrada: ${e.efi_temprana.cpt?'US$'+fmt(e.efi_temprana.cpt,2):'—'} con más de 30 días de anticipación y ${e.efi_final.cpt?'US$'+fmt(e.efi_final.cpt,2):'—'} en los últimos 30.</p><div class=\"ch l\"><canvas id=\"c-diario\"></canvas></div></div>\n  <div class=\"grid2\">\n   <div class=\"card\"><h3>¿Cuándo se vende?</h3><p class=\"sub\">% de las entradas según semanas antes de la primera función.</p><div class=\"ch\"><canvas id=\"c-buck\"></canvas></div></div>\n   <div class=\"card\"><h3>Comparado con eventos parecidos</h3><p class=\"sub\">Venta acumulada de este evento (morado) y de los anteriores del mismo tipo (gris).</p><div class=\"ch\"><canvas id=\"c-curva\"></canvas></div></div>\n  </div>\n  <div class=\"grid2\">\n   <div class=\"card\"><h3>Zonas y precios</h3><table><thead><tr><th>Zona / tramo</th><th class=\"n\">Precio</th><th class=\"n\">Entradas</th><th class=\"n\">% de la venta</th></tr></thead><tbody>${e.zonas.map(z=>`<tr><td>${z[0]}</td><td class=\"n\">${clp(z[3])}</td><td class=\"n\">${fmt(z[1])}</td><td class=\"n\">${pct(100*z[2]/zt,1)}</td></tr>`).join('')}</tbody></table></div>\n   <div class=\"card\"><h3>Funciones y canales de venta</h3><table><thead><tr><th>Función</th><th class=\"n\">Venta</th></tr></thead><tbody>${e.funcs.map(f=>`<tr><td>${f[0]}</td><td class=\"n\">${clp(f[1])}</td></tr>`).join('')}</tbody></table><br><table><thead><tr><th>Canal en Ticketplus</th><th class=\"n\">Entradas</th><th class=\"n\">%</th></tr></thead><tbody>${e.canales.filter(c=>c[1]/ct>=0.002).map(c=>`<tr><td>${c[0]==='Online'?'Link directo (Merlin, Meta, orgánico)':c[0]==='google_ads_tp'?'Booster Ticketplus (Google)':c[0]}</td><td class=\"n\">${fmt(c[1])}</td><td class=\"n\">${pct(100*c[1]/ct,1)}</td></tr>`).join('')}</tbody></table>\n   <p class=\"sub\" style=\"margin-top:12px\">Campañas Meta: ${e.campanas.map(c=>`<span class=\"pill\">${c}</span>`).join('')||'—'}</p></div>\n  </div>\n  <div class=\"card\"><h3>Anuncios del evento</h3><p class=\"sub\">Ordenados por compras que Meta se atribuye.</p><div class=\"ads\">${adsHTML(ads.slice(0,12))}</div></div>`;\n  $('#evsel').onchange=ev=>{SEL=ev.target.value;render.evento()};\n  const d=e.diario;\n  chart('c-diario',{data:{labels:d.map(r=>r[0]),datasets:[{type:'bar',label:'Entradas vendidas',data:d.map(r=>r[1]),backgroundColor:'#c9c1f7',borderRadius:3,yAxisID:'y'},{type:'line',label:'Inversión Meta (US$)',data:d.map(r=>r[3]),borderColor:'#e9a400',pointRadius:0,borderWidth:2.2,tension:.25,yAxisID:'y1'}]},\n   options:{maintainAspectRatio:false,interaction:{mode:'index',intersect:false},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:12,callback:function(v){const s=this.getLabelForValue(v);return +s.slice(8)+' '+MES[+s.slice(5,7)-1]}}},y:{grid:{color:'#f0eef7'},title:{display:true,text:'entradas'}},y1:{position:'right',grid:{display:false},title:{display:true,text:'US$'}}}}});\n  const bk=Object.entries(e.buckets);\n  chart('c-buck',{type:'bar',data:{labels:bk.map(b=>b[0]),datasets:[{data:bk.map(b=>b[1]),backgroundColor:['#1d1640','#3a2a7a','#5b47d6','#8b7bf0','#c9c1f7','#e9c349'],borderRadius:6}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{grid:{color:'#f0eef7'},ticks:{callback:v=>v+'%'}}}}});\n  curvaChart('c-curva',e,false);\n};\nfunction adsHTML(l){return l.map(a=>`<div class=\"ad\">${a.thumb?`<img loading=\"lazy\" src=\"${a.thumb}\" onerror=\"this.style.display='none'\">`:''}<div class=\"c\"><b>${a.ad}</b><span class=\"pill\">${a.formato}</span><div style=\"margin-top:6px\">${fmt(a.compras)} compras · ${usd(a.gasto)} · <b style=\"display:inline\">${fmt(a.r,1)}x</b></div><p>${(a.body||'').replace(/</g,'&lt;')}</p></div></div>`).join('')}\n\n/* ======== LO QUE ENSEÑA LA HISTORIA ======== */\nfunction recompraHTML(){const r=D.recompra;if(!r)return'';const rp=100*r.rep.n/r.compradores,rt=100*r.rep.ventas/r.ventas,act=100*r.actual.ya_compraron_2025/r.actual.compradores;\n const pe=r.porEvento.filter(p=>p[1]>=150).sort((a,b)=>b[2]-a[2]);\n return `<p class=\"sub\">${r.fuente}</p><div class=\"hacer\" style=\"margin:10px 0 14px;background:#fff7ed;border-color:#fdba74\"><b>En revisión (24 nov)</b>Estas cifras miran un solo año (2025). No miden cuánto del público de un evento ya había venido antes a Merlin, que según Merlin es 30–40 % en ópera, sinfónicos y ballet. Para medirlo estamos cruzando cada evento con todos los anteriores en Ticketplus (5 de 2024, 23 de 2025 y 23 de 2026); hasta ahora solo se había cruzado con 2025.</div>\n <div class=\"kpis\"><div class=\"kpi\"><div class=\"v\">${fmt(r.compradores)}</div><div class=\"l\">compradores distintos en 2025</div><div class=\"s\">${fmt(r.tickets)} entradas online</div></div>\n <div class=\"kpi\"><div class=\"v\">${pct(100-rp,0)}</div><div class=\"l\">compró un solo evento dentro de 2025</div><div class=\"s\">${fmt(r.dist['1'])} personas</div></div>\n <div class=\"kpi\"><div class=\"v\">${pct(rp,1)}</div><div class=\"l\">compró 2 o más eventos dentro de 2025</div><div class=\"s\">${fmt(r.dist['2'])} dos · ${fmt(r.dist['3'])} tres · ${fmt(r.dist['4'])} cuatro o más</div></div>\n <div class=\"kpi\"><div class=\"v\">${pct(rt,0)}</div><div class=\"l\">de la venta viene de quienes repiten</div><div class=\"s\">${mm(r.rep.ventas)} · ${fmt(r.rep.tickets/r.rep.n,1)} entradas por persona vs ${fmt((r.tickets-r.rep.tickets)/(r.compradores-r.rep.n),1)}</div></div>\n </div>\n <div class=\"grid2\"><div><h3 style=\"font-size:15px\">% de compradores que venían de otro evento de Merlin</h3><table><thead><tr><th>Evento 2025</th><th class=\"n\">Compradores</th><th class=\"n\">Compraron otro evento 2025</th></tr></thead><tbody>${pe.map(p=>`<tr><td>${p[0]}</td><td class=\"n\">${fmt(p[1])}</td><td class=\"n ${p[2]>=20?'ok':''}\">${p[2]}%</td></tr>`).join('')}</tbody></table></div>\n <div><h3 style=\"font-size:15px\">De qué evento a cuál se mueve el público</h3><table><thead><tr><th>Primero compró</th><th>Después compró</th><th class=\"n\">Personas</th></tr></thead><tbody>${r.pares.map(p=>`<tr><td>${p[0]}</td><td>${p[1]}</td><td class=\"n\">${p[2]}</td></tr>`).join('')}</tbody></table>\n <div class=\"hacer\" style=\"margin-top:14px\"><b>Palanca</b>Quien vuelve compra más entradas por persona. Público personalizado con los compradores anteriores (Meta) y correo a la base al abrir cada venta, sobre todo cruzando ópera ↔ gala lírica y Strauss ↔ flamenco/Queen, que es donde ya se mueve la gente.</div></div></div>`}\nfunction lblES(k){const [a,g]=k.split('|');return a+' '+(g==='female'?'mujeres':g==='male'?'hombres':'s/d')}\nfunction agFormato(){const o={};for(const c of D.creatividades){if(!c.slug)continue;const f=c.formato;o[f]=o[f]||{g:0,c:0,v:0};o[f].g+=c.gasto;o[f].c+=c.compras;o[f].v+=c.valor}for(const k in o){o[k].r=o[k].v/Math.max(1,o[k].g);o[k].cpa=o[k].g/Math.max(1,o[k].c)}return o}\nfunction agSeg(n,tipo){const o={};for(const [t,k,g,c,v] of D.segmentos[n]){if(tipo&&t!==tipo)continue;if(n!=='region'&&t==='Sin evento')continue;o[k]=o[k]||{k,g:0,c:0,v:0};o[k].g+=g;o[k].c+=c;o[k].v+=v}return Object.values(o).map(x=>({...x,r:x.v/Math.max(1,x.g),cpa:x.g/Math.max(1,x.c)}))}\nconst BANDAS=[[0,30000,'Hasta $30 mil'],[30000,45000,'$30–45 mil'],[45000,65000,'$45–65 mil'],[65000,85000,'$65–85 mil'],[85000,1e12,'Más de $85 mil']];\nfunction agZonas(lista=E){const o=BANDAS.map(b=>({l:b[2],q:0,m:0}));for(const e of lista)for(const [n,q,m,p] of e.zonas){const i=BANDAS.findIndex(b=>p>=b[0]&&p<b[1]);if(i>=0){o[i].q+=q;o[i].m+=m}}return o}\nfunction agCanales(lista=E){const o={};for(const e of lista)for(const [k,q,m] of e.canales){o[k]=o[k]||{k,q:0,m:0};o[k].q+=q;o[k].m+=m}return Object.values(o).sort((a,b)=>b.q-a.q)}\nfunction tiposTabla(){return TIPOS.map(t=>{const l=REAL.filter(e=>e.tipo===t&&e.gasto>0);if(!l.length)return null;const g=l.reduce((a,e)=>a+e.gasto,0),i=l.reduce((a,e)=>a+e.ingresos,0),k=l.reduce((a,e)=>a+e.tickets_tp,0);const m=f=>l.reduce((a,e)=>a+e[f],0)/l.length;return {t,n:l.length,i,k,r:i/(g*USD),cpt:g/k,oc:m('ocupacion'),a30:m('antes30'),u14:m('ult14'),p7:m('primeros7'),p:i/k}}).filter(Boolean).sort((a,b)=>b.r-a.r)}\nfunction palancas(){\n  const R=D.resumen,T=tiposTabla();const best=T[0],worst=T[T.length-1];\n  const late=T.filter(t=>t.u14>=20).map(t=>t.t),early=T.filter(t=>t.a30>=60).map(t=>t.t);\n  const cr=agFormato();const pl=agSeg('plataforma').filter(x=>x.g>10000).sort((a,b)=>b.r-a.r),es=agSeg('edad_sexo').filter(x=>x.g>8000).sort((a,b)=>b.r-a.r);\n  const zon=agZonas();const zt=zon.reduce((a,z)=>a+z.m,0);const zmid=zon.filter(z=>z.l==='$45–65 mil'||z.l==='$65–85 mil').reduce((a,z)=>a+z.m,0);\n  const can=agCanales();const tot=can.reduce((a,c)=>a+c.q,0);const tp=can.filter(c=>c.k!=='Online').reduce((a,c)=>a+c.q,0);\n  return [\n   ['Calendario','Unos títulos se venden temprano y otros a última hora',`${early.join(', ')}: más del 60% de las entradas se vende con más de 30 días de anticipación. ${late.join(', ')}: 20–30% se vende en las 2 últimas semanas.`,'Pauta fuerte al abrir la venta en los tempraneros; guardar 30–40% del presupuesto para el cierre en galas y musicales.'],\n   ['Costo','Vender temprano cuesta menos',`Mediana de ${R.n_fase} eventos: US$${fmt(R.cpt_temprano,1)} de Meta por entrada vendida con más de 30 días, contra US$${fmt(R.cpt_final,1)} en los últimos 30 (+${fmt(100*(R.cpt_final/R.cpt_temprano-1))}%).`,'Abrir con preventa y pauta fuerte las 2–3 primeras semanas.'],\n   ['Títulos',`${best.t} retorna ${fmt(best.r,1)}x; ${worst.t}, ${fmt(worst.r,1)}x`,T.map(t=>`${t.t} ${fmt(t.r,1)}x`).join(' · '),`Asignar presupuesto según el retorno histórico del tipo: más a ${best.t}, tope a ${worst.t}.`],\n   ['Días','El fin de semana vende más',`Sábado y domingo concentran ${pct(R.fds,1)} de las entradas; cada día hábil, 13–14%.`,'Subir la inversión de viernes a domingo y anunciar novedades el jueves.'],\n   ['Precio',`Las zonas de $45–85 mil hacen ${pct(100*zmid/zt)} del ingreso`,`Sobre $85 mil se vende poco (${pct(100*(zon.find(z=>/Más/.test(z.l))?.m||0)/zt,1)} del ingreso).`,'Subir el tramo medio a medida que se llena; no ampliar la zona premium.'],\n   ['Creatividad','Imagen y video rinden parecido',`Imagen ${fmt(cr.imagen?.r,2)}x y video ${fmt(cr.video?.r,2)}x según Meta (US$${fmt(cr.imagen?.cpa,1)} y US$${fmt(cr.video?.cpa,1)} por compra).`,'No sobreinvertir en video: rotar afiches fuertes y cápsulas cortas.'],\n   ['Ubicaciones',`Feed de Instagram es lo que mejor retorna`,`Mejores: ${pl.slice(0,3).map(x=>`${x.k.replace(/_/g,' ')} ${fmt(x.r,2)}x`).join(' · ')}. Peor: ${pl.slice(-1).map(x=>`${x.k.replace(/_/g,' ')} ${fmt(x.r,2)}x`).join('')}.`,'Excluir Audience Network y concentrar en feed de Instagram.'],\n   ['Público','45–64 años retorna más que 18–34',`Mejores: ${es.slice(0,3).map(x=>`${lblES(x.k)} ${fmt(x.r,2)}x`).join(' · ')}. Más débiles: ${es.slice(-3).map(x=>`${lblES(x.k)} ${fmt(x.r,2)}x`).join(' · ')}.`,'Concentrar en 35–65+; 18–34 solo para tributos y Broadway.'],\n   ['Canal',`${pct(100*(tot-tp)/tot,1)} entra por el link directo`,`Los canales propios de Ticketplus (Booster con Google, home, mailing) suman ${pct(100*tp/tot,1)}.`,'Cada anuncio con UTM propia para separar lo que vende Meta.'],\n  ];\n}\nrender.aprende=()=>{\n  const P=D.aprendizaje.precision,T=tiposTabla();\n  $('#s-aprende').innerHTML=`<div class=\"cap\"><span class=\"num\">00</span><div><h2>Lo que enseña la historia de Merlin</h2><p>Las 9 palancas, en una línea cada una.</p></div></div>\n  <div class=\"card\"><p class=\"lead\" style=\"margin-top:0\">${REAL.length} eventos realizados y ${fmt(D.creatividades.length)} anuncios. Cada vez que termina un evento, entra a esta base y las predicciones y referencias de ahorro se recalculan con él.</p>\n  <div class=\"grid3\">${palancas().map((p,i)=>`<div class=\"pal\"><div class=\"n\">${i+1} · ${p[0]}</div><h4>${p[1]}</h4><p>${p[2]}</p><div class=\"a\">→ ${p[3]}</div></div>`).join('')}</div></div>\n  <div class=\"cap\"><span class=\"num\">01</span><div><h2>Cuándo se vende</h2><p>Unos títulos venden temprano y otros a última hora; el fin de semana pesa más.</p></div></div>\n  <div class=\"grid2\"><div class=\"card\"><h3>Cómo se vende cada tipo</h3><p class=\"sub\">% de la venta final acumulada según días antes de la función.</p><div class=\"ch l\"><canvas id=\"c-curvas\"></canvas></div></div>\n  <div class=\"card\"><h3>Día de la semana</h3><p class=\"sub\">% de las entradas por día de compra.</p><div class=\"ch l\"><canvas id=\"c-sem\"></canvas></div></div></div>\n  <div class=\"cap\"><span class=\"num\">02</span><div><h2>Qué rinde</h2><p>Retorno por tipo de evento, inversión contra venta y precios.</p></div></div>\n  <div class=\"card\"><h3>Por tipo de evento</h3><table><thead><tr><th>Tipo</th><th class=\"n\">Eventos</th><th class=\"n\">Venta</th><th class=\"n\">Precio prom.</th><th class=\"n\">Retorno</th><th class=\"n\">US$ por entrada</th><th class=\"n\">Ocupación</th><th class=\"n\">Con +30 días</th><th class=\"n\">2 últimas sem.</th></tr></thead><tbody>${T.map(t=>`<tr><td><b style=\"color:${tcol(t.t)}\">●</b> ${t.t}</td><td class=\"n\">${t.n}</td><td class=\"n\">${mm(t.i)}</td><td class=\"n\">${clp(t.p)}</td><td class=\"n\">${fmt(t.r,1)}x</td><td class=\"n\">${fmt(t.cpt,2)}</td><td class=\"n\">${pct(t.oc)}</td><td class=\"n\">${pct(t.a30)}</td><td class=\"n\">${pct(t.u14)}</td></tr>`).join('')}</tbody></table></div>\n  <div class=\"grid2\"><div class=\"card\"><h3>Inversión y venta por evento</h3><p class=\"sub\">Cada punto, un evento realizado.</p><div class=\"ch l\"><canvas id=\"c-scat\"></canvas></div></div>\n  <div class=\"card\"><h3>Venta por tramo de precio</h3><div class=\"ch l\"><canvas id=\"c-zon\"></canvas></div></div></div>\n  <div class=\"cap\"><span class=\"num\">03</span><div><h2>Quién compra</h2><p>Público nuevo, recompra y cómo se mueve la gente entre títulos.</p></div></div>\n  <div class=\"card\"><h3>Público nuevo y recompra</h3>${recompraHTML()}</div>\n  <div class=\"cap\"><span class=\"num\">04</span><div><h2>Qué tan confiable es la predicción</h2><p>El modelo probado contra cada evento ya realizado.</p></div></div>\n  <div class=\"card\"><h3>¿Qué tan bien predice el modelo?</h3><p class=\"sub\">Se probó con cada evento ya realizado como si estuviera en venta: con lo vendido hasta ese día y los demás eventos como historia. Error típico de la proyección final según los días que faltaban.</p>\n  <div class=\"prec\">${['60','45','30','14','7'].map(d=>P[d]?`<div><div class=\"v\">±${fmt(P[d].mediana)}%</div><div class=\"l\">a ${d} días · ${P[d].dentro15}% de los eventos con error menor a 15%</div></div>`:'').join('')}</div>\n  <p class=\"sub\" style=\"margin-top:14px\">A más de 45 días es una orientación; desde 30 días la proyección ya es confiable para decidir inversión.</p></div>\n  <div class=\"cap\"><span class=\"num\">05</span><div><h2>Todos los eventos realizados</h2><p>Click en un evento para ver su detalle.</p></div></div>\n  <div class=\"card\"><h3>Todos los eventos realizados</h3><div style=\"overflow:auto\"><table id=\"tev\"><thead><tr><th>Fecha</th><th>Evento</th><th>Tipo</th><th>Ciudad</th><th class=\"n\">Entradas</th><th class=\"n\">Ocupación</th><th class=\"n\">Venta</th><th class=\"n\">Meta US$</th><th class=\"n\">Retorno</th><th class=\"n\">Con +30 días</th><th>Perfil</th></tr></thead><tbody>${REAL.map(e=>`<tr data-s=\"${e.slug}\" style=\"cursor:pointer\"><td>${fecha(e.fecha)}</td><td>${e.nombre}</td><td>${e.tipo}</td><td>${e.ciudad}</td><td class=\"n\">${fmt(e.tickets_tp)}</td><td class=\"n\">${pct(e.ocupacion)}</td><td class=\"n\">${mm(e.ingresos)}</td><td class=\"n\">${fmt(e.gasto)}</td><td class=\"n\">${e.gasto?fmt(roas(e),1)+'x':'—'}</td><td class=\"n\">${pct(e.antes30)}</td><td><span class=\"chip c-gr\">${e.perfil}</span></td></tr>`).join('')}</tbody></table></div></div>`;\n  $('#tev tbody').onclick=ev=>{const tr=ev.target.closest('tr');if(!tr)return;SEL=tr.dataset.s;ir('evento')};\n  const xs=[120,90,75,60,45,30,21,14,7,3,0];\n  chart('c-curvas',{type:'line',data:{labels:xs.map(x=>-x),datasets:TIPOS.map(t=>{const l=REAL.filter(e=>e.tipo===t);return{label:t,data:xs.map(x=>100*l.reduce((a,e)=>{let f=0;for(const [d,c] of e.curva)if(d>=x)f=c;return a+f},0)/l.length),borderColor:tcol(t),backgroundColor:tcol(t),tension:.35,borderWidth:2.5,pointRadius:2}})},options:{maintainAspectRatio:false,scales:{x:{grid:{display:false},title:{display:true,text:'días antes de la función'},ticks:{callback:function(v){return -this.getLabelForValue(v)}}},y:{min:0,max:100,grid:{color:'#f0eef7'},ticks:{callback:v=>v+'%'}}}}});\n  const w=D.resumen.semana,ws=w.reduce((a,b)=>a+b,0);\n  chart('c-sem',{type:'bar',data:{labels:['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'],datasets:[{data:w.map(x=>+(100*x/ws).toFixed(1)),backgroundColor:w.map((x,i)=>i>=5?'#5b47d6':'#d9d3fb'),borderRadius:8}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{grid:{color:'#f0eef7'},ticks:{callback:v=>v+'%'}}}}});\n  const pts=REAL.filter(e=>e.gasto);\n  chart('c-scat',{type:'scatter',data:{datasets:TIPOS.map(t=>({label:t,data:pts.filter(e=>e.tipo===t).map(e=>({x:e.gasto,y:e.ingresos/1e6,n:e.nombre})),backgroundColor:tcol(t),pointRadius:6}))},options:{maintainAspectRatio:false,plugins:{tooltip:{callbacks:{label:c=>`${c.raw.n}: ${usd(c.raw.x)} → ${mm(c.raw.y*1e6)}`}}},scales:{x:{grid:{color:'#f0eef7'},title:{display:true,text:'Inversión Meta US$'}},y:{grid:{color:'#f0eef7'},title:{display:true,text:'Venta CLP MM'}}}}});\n  const z=agZonas();chart('c-zon',{type:'bar',data:{labels:z.map(x=>x.l),datasets:[{label:'Venta (CLP MM)',data:z.map(x=>Math.round(x.m/1e6)),backgroundColor:'#5b47d6',borderRadius:6},{label:'Entradas',data:z.map(x=>x.q),backgroundColor:'#e9c349',borderRadius:6,yAxisID:'y1'}]},options:{maintainAspectRatio:false,scales:{x:{grid:{display:false}},y:{grid:{color:'#f0eef7'},title:{display:true,text:'CLP MM'}},y1:{position:'right',grid:{display:false},title:{display:true,text:'entradas'}}}}});\n};\n\n/* ======== PÚBLICOS ======== */\nlet STIPO='';\nrender.seg=()=>{\n  const es=agSeg('edad_sexo',STIPO),pl=agSeg('plataforma',STIPO),rg=agSeg('region',STIPO);\n  const edades=['18-24','25-34','35-44','45-54','55-64','65+'];const g=(a,s)=>es.find(x=>x.k===a+'|'+s)||{g:0,r:0};\n  const tg=es.reduce((a,y)=>a+y.g,0);\n  $('#s-seg').innerHTML=`<div class=\"row\"><b>Tipo de evento</b><select id=\"stipo\"><option value=\"\">Todos</option>${TIPOS.map(t=>`<option ${t===STIPO?'selected':''}>${t}</option>`).join('')}</select></div>\n  <div class=\"grid2\"><div class=\"card\"><h3>Edad y sexo</h3><p class=\"sub\">Barras: inversión. Líneas: retorno según Meta.</p><div class=\"ch l\"><canvas id=\"c-es\"></canvas></div></div>\n  <div class=\"card\"><h3>Qué segmentos retornan más</h3><table><thead><tr><th>Segmento</th><th class=\"n\">Inversión</th><th class=\"n\">% del total</th><th class=\"n\">US$ por compra</th><th class=\"n\">Retorno</th></tr></thead><tbody>${es.filter(x=>x.g>2000).sort((a,b)=>b.r-a.r).map(x=>`<tr><td>${lblES(x.k)}</td><td class=\"n\">${usd(x.g)}</td><td class=\"n\">${pct(100*x.g/tg,1)}</td><td class=\"n\">${fmt(x.cpa,1)}</td><td class=\"n ${x.r>=3.3?'ok':x.r<2.9?'ri':''}\">${fmt(x.r,2)}x</td></tr>`).join('')}</tbody></table></div></div>\n  <div class=\"grid2\"><div class=\"card\"><h3>Ubicaciones</h3><table><thead><tr><th>Ubicación</th><th class=\"n\">Inversión</th><th class=\"n\">US$ por compra</th><th class=\"n\">Retorno</th></tr></thead><tbody>${pl.filter(x=>x.g>2000).sort((a,b)=>b.g-a.g).map(x=>`<tr><td>${x.k.replace(/_/g,' ')}</td><td class=\"n\">${usd(x.g)}</td><td class=\"n\">${fmt(x.cpa,1)}</td><td class=\"n ${x.r>=3.3?'ok':x.r<2.6?'ri':''}\">${fmt(x.r,2)}x</td></tr>`).join('')}</tbody></table></div>\n  <div class=\"card\"><h3>Regiones</h3><p class=\"sub\">Meta no entrega compras por región; se muestra dónde se invirtió.</p><table><thead><tr><th>Región</th><th class=\"n\">Inversión</th><th class=\"n\">%</th></tr></thead><tbody>${rg.filter(x=>x.g>300).sort((a,b)=>b.g-a.g).slice(0,12).map(x=>`<tr><td>${x.k}</td><td class=\"n\">${usd(x.g)}</td><td class=\"n\">${pct(100*x.g/rg.reduce((a,y)=>a+y.g,0),1)}</td></tr>`).join('')}</tbody></table></div></div>`;\n  $('#stipo').onchange=ev=>{STIPO=ev.target.value;render.seg()};\n  chart('c-es',{data:{labels:edades,datasets:[{type:'bar',label:'Inversión mujeres',data:edades.map(a=>g(a,'female').g),backgroundColor:'#d9d3fb',borderRadius:6,yAxisID:'y'},{type:'bar',label:'Inversión hombres',data:edades.map(a=>g(a,'male').g),backgroundColor:'#bfe3f7',borderRadius:6,yAxisID:'y'},{type:'line',label:'Retorno mujeres',data:edades.map(a=>+g(a,'female').r.toFixed(2)),borderColor:'#5b47d6',borderWidth:2.5,yAxisID:'y1'},{type:'line',label:'Retorno hombres',data:edades.map(a=>+g(a,'male').r.toFixed(2)),borderColor:'#0ea5e9',borderWidth:2.5,yAxisID:'y1'}]},options:{maintainAspectRatio:false,scales:{x:{grid:{display:false}},y:{grid:{color:'#f0eef7'},title:{display:true,text:'US$'}},y1:{position:'right',grid:{display:false},title:{display:true,text:'retorno'}}}}});\n};\n\n/* ======== CREATIVIDAD ======== */\nlet CTIPO='';\nrender.crea=()=>{\n  const l=D.creatividades.filter(c=>c.slug&&c.gasto>20&&(!CTIPO||c.tipo_ev===CTIPO)).map(c=>({...c,r:c.valor/c.gasto}));\n  const f={};for(const c of l){f[c.formato]=f[c.formato]||{g:0,c:0,v:0,n:0};f[c.formato].g+=c.gasto;f[c.formato].c+=c.compras;f[c.formato].v+=c.valor;f[c.formato].n++}\n  const top=l.filter(c=>c.gasto>300).sort((a,b)=>b.r-a.r).slice(0,12),bot=l.filter(c=>c.gasto>500).sort((a,b)=>a.r-b.r).slice(0,8);\n  $('#s-crea').innerHTML=`<div class=\"row\"><b>Tipo de evento</b><select id=\"ctipo\"><option value=\"\">Todos</option>${TIPOS.map(t=>`<option ${t===CTIPO?'selected':''}>${t}</option>`).join('')}</select></div>\n  <div class=\"kpis\">${Object.entries(f).filter(([k])=>k!=='s/d').map(([k,v])=>`<div class=\"kpi\"><div class=\"v\">${fmt(v.v/v.g,2)}x</div><div class=\"l\">${k[0].toUpperCase()+k.slice(1)}: retorno según Meta</div><div class=\"s\">${v.n} anuncios · ${usd(v.g)} · US$${fmt(v.g/Math.max(1,v.c),1)} por compra</div></div>`).join('')}</div>\n  <div class=\"card\"><h3>Los que mejor retornan</h3><p class=\"sub\">Anuncios con más de US$300 de inversión.</p><div class=\"ads\">${adsHTML(top)}</div></div>\n  <div class=\"card\"><h3>Los que menos retornan</h3><p class=\"sub\">Anuncios con más de US$500 de inversión.</p><div class=\"ads\">${adsHTML(bot)}</div></div>`;\n  $('#ctipo').onchange=ev=>{CTIPO=ev.target.value;render.crea()};\n};\n\n/* ======== MÉTODO ======== */\nrender.metodo=()=>{$('#s-metodo').innerHTML=`<div class=\"card\"><h2>Cómo se calcula</h2><div class=\"note\">\n<p><b>Ticketplus:</b> venta, entradas, venta diaria, por función, zonas y canales de cada evento de MERLIN COMUNICACIONES SpA (${E.length} eventos con venta). Sin cargo por servicio; las cortesías no cuentan como venta.</p>\n<p><b>Meta Ads:</b> cuentas «Merlin Ad Account» y «Merlin 2», desde enero de 2025, en US$. Cada campaña se asocia a su evento por nombre, ciudad y fechas. ${usd(D.sin_evento.gasto)} corresponde a campañas sin evento en esta cuenta de Ticketplus (por ejemplo Carmen en Lima).</p>\n<p><b>Retorno</b> = venta Ticketplus ÷ (inversión Meta × ${USD} CLP por US$). Incluye ventas de otras fuentes (orgánico, prensa, Booster de Ticketplus).</p>\n<p><b>Predicción:</b> combina dos lecturas de la historia de Merlin: (1) qué porcentaje de su venta final tenían los eventos parecidos a los mismos días de la función y (2) cuántas entradas más vendieron después, en relación con su ritmo de la última semana. Se promedian, con tope en la capacidad. Se probó con los ${REAL.length} eventos realizados (pestaña «Lo que enseña la historia»).</p>\n<p><b>Ahorro:</b> se compara el costo por compra de los últimos 14 días de cada campaña, conjunto y anuncio activo con el costo histórico del mismo tipo de evento en la misma etapa. Se marca para pausar lo que cuesta más de 1,6 veces lo histórico con inversión relevante, las ubicaciones y edades que históricamente retornan poco, y la inversión que sobra en eventos que se van a agotar. «Ahorro» = inversión diaria de eso × 14 días (o los que falten, si son menos); los eventos que se agotan nunca se recortan más de 40%. Se recalcula cada semana. «Mover» = inversión que conviene pasar a lo que sí rinde dentro de la misma campaña.</p>\n<p><b>Ocupación:</b> entradas ÷ (capacidad registrada en Ticketplus × funciones). Referencial.</p></div></div>`};\nrender.resumen();$('#s-resumen').classList.add('on');\nif(location.hash){const k=location.hash.slice(1);if(S[k])ir(k)}\n</script>\n</body>\n</html>\n"
